  const opts = { minSize: 14, maxSize: 22, minViewport: 375, maxViewport: 1440 };
  const css = fluidType(opts);
  const m = css.match(/clamp\\(([-0-9.]+)rem, ([-0-9.]+)rem ([+-]) ([0-9.]+)vw, ([-0-9.]+)rem\\)/);
